// Title: Weekend Starts Here
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates (-1 to 1)
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;

    // Clock face - Red circle
    float clockRadius = 0.4;
    float clockFace = smoothstep(clockRadius, clockRadius + 0.01, length(uv));

    // Time logic (simulating real clock but speeding up near 5PM)
    float t = mod(iTime, 60.0); // Full loop every 60 seconds

    // **Shift animation BACK by exactly 5 hours (-5π/6 radians)**
    float angleOffset = -(5.0 * 3.14159265359 / 6.0);  

    // **Reverse direction** & apply the corrected shift
    float hourHandAngle = 3.14 / 2.0 - (t / 60.0) * 2.0 * 3.14 + angleOffset;  
    float minuteHandAngle = 3.14 / 2.0 - (t / 12.0) * 2.0 * 3.14 + angleOffset;

    // Hand positions
    vec2 hourHand = vec2(cos(hourHandAngle), sin(hourHandAngle)) * 0.25;
    vec2 minuteHand = vec2(cos(minuteHandAngle), sin(minuteHandAngle)) * 0.35;

    // Hand thickness
    float handThickness = 0.02;

    // Draw clock hands (white)
    float hourLine = smoothstep(handThickness, handThickness + 0.01, length(uv - hourHand));
    float minuteLine = smoothstep(handThickness, handThickness + 0.01, length(uv - minuteHand));

    // **Friday 5PM HYPE EFFECT!** (Pulse at 5PM)
    float pulseEffect = smoothstep(0.9, 1.0, sin(iTime * 10.0)) * step(58.0, t);

    // Combine layers
    vec3 color = vec3(0.0); // Black background
    color += vec3(1.0, 0.0, 0.0) * (1.0 - clockFace); // Red clock face
    color += vec3(1.0) * (1.0 - hourLine);  // White hour hand
    color += vec3(1.0) * (1.0 - minuteLine); // White minute hand
    color += vec3(pulseEffect, 0.0, 0.0); // Red pulse effect at 5PM

    fragColor = vec4(color, 1.0);
}
